          || (cnt == 4 && (nl[cnt].n_value != 0 || nl[cnt].n_scnum != 0
                   || nl[cnt].n_type != 0 || nl[cnt].n_sclass != 0
                   || nl[cnt].n_numaux != 0)))
        result = 1;
    }

  return foo (result);
}
